UPDATE wms_purchase_inspection
SET recheck_method = #{recheck.method}, recheck_checked = #{recheck.checkedQuantity},
    recheck_passed = #{recheck.passedQuantity}, recheck_failed = #{recheck.failedQuantity},
    recheck_operator_id = #{recheck.operatorId}, rechecked_at = #{recheck.checkedAt}
WHERE tenant_id = #{tenantId} AND batch_no = #{batchNo}

UPDATE wms_purchase_inspection
SET good_quantity = #{good}, defective_quantity = #{defective},
    disposition_operator_id = #{operatorId}, disposed_at = #{disposedAt}
WHERE tenant_id = #{tenantId} AND batch_no = #{batchNo}
